class BizException extends Error {
  constructor(code, message){ super(message); this.code = code; this.biz = true; }
}

function safeHandle(err) {
  if (err.biz) return { code: err.code, message: err.message, stack: undefined };
  return { code: 500, message: "系统繁忙，请稍后再试", stack: "（已隐藏）" };
}
const biz = new BizException(2001, "余额不足");
const sys = new Error("TypeError: cannot read property");
console.log(JSON.stringify(safeHandle(biz)));
console.log(JSON.stringify(safeHandle(sys)));
